-- Tabla y secuencia que en Supabase existen fuera de las entidades JPA.
CREATE TABLE IF NOT EXISTS producto_sku_consecutivos (
    restaurante_id UUID PRIMARY KEY,
    ultimo_numero  BIGINT NOT NULL,
    actualizado_en TIMESTAMP NOT NULL
);
CREATE SEQUENCE IF NOT EXISTS restaurante_codigo_seq START WITH 2;


